BEGIN;
SET LOCAL search_path=pg_catalog;
SELECT 1/(current_database()='subtrack_sandbox' AND SESSION_USER='subtrack_sandbox_bootstrap' AND current_setting('server_version_num')::int BETWEEN 160000 AND 169999 AND EXISTS(SELECT 1 FROM st250_auth.epoch WHERE id='st250-sandbox-v1' AND manifest_h=current_setting('st250.manifest') AND active))::int;
CREATE TYPE public.subscription_cadence AS ENUM('WEEKLY','MONTHLY','QUARTERLY','SEMIANNUAL','ANNUAL','CUSTOM');
CREATE TYPE public.subscription_status AS ENUM('DETECTED','ACTIVE','PAUSED','CANCELLED','ARCHIVED','REJECTED');
CREATE TYPE public.subscription_source AS ENUM('MANUAL');
CREATE TABLE public.identity_profile(identity_id uuid PRIMARY KEY REFERENCES public.identity(id) ON DELETE RESTRICT,display_name varchar(120),avatar_color varchar(32),avatar_emoji varchar(32),language varchar(2) NOT NULL CHECK(language IN('sv','en')),theme varchar(16) NOT NULL CHECK(theme IN('system','light','dark')),default_currency char(3) NOT NULL CHECK(default_currency='SEK'),profile_complete boolean NOT NULL CHECK(NOT profile_complete OR display_name IS NOT NULL),onboarding_mode varchar(16) CHECK(onboarding_mode='just-me'),updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE public.merchant(id uuid PRIMARY KEY,canonical_name varchar(120) NOT NULL);
CREATE TABLE public.subscription(id uuid PRIMARY KEY,identity_id uuid NOT NULL REFERENCES public.identity(id) ON DELETE RESTRICT,merchant_id uuid REFERENCES public.merchant(id) ON DELETE RESTRICT,source public.subscription_source NOT NULL CHECK(source='MANUAL'),custom_name varchar(120) NOT NULL,category_code varchar(50) NOT NULL,cadence public.subscription_cadence NOT NULL CHECK(cadence<>'CUSTOM'),expected_amount_minor bigint NOT NULL CHECK(expected_amount_minor>0),currency char(3) NOT NULL CHECK(currency='SEK'),status public.subscription_status NOT NULL CHECK(status IN('ACTIVE','PAUSED','CANCELLED','ARCHIVED')),next_charge_date date,always_private boolean NOT NULL CHECK(always_private),revision bigint NOT NULL DEFAULT 1 CHECK(revision>0),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(id,identity_id));
CREATE TABLE public.manual_subscription_create_receipt(identity_id uuid NOT NULL,key_hash bytea NOT NULL CHECK(octet_length(key_hash)=32),request_hash bytea NOT NULL CHECK(octet_length(request_hash)=32),subscription_id uuid NOT NULL,PRIMARY KEY(identity_id,key_hash),FOREIGN KEY(subscription_id,identity_id) REFERENCES public.subscription(id,identity_id) ON DELETE RESTRICT);
CREATE TABLE public.manual_subscription_edit_receipt(identity_id uuid NOT NULL,key_hash bytea NOT NULL CHECK(octet_length(key_hash)=32),request_hash bytea NOT NULL CHECK(octet_length(request_hash)=32),subscription_id uuid NOT NULL,result_revision bigint NOT NULL CHECK(result_revision>0),PRIMARY KEY(identity_id,key_hash),FOREIGN KEY(subscription_id,identity_id) REFERENCES public.subscription(id,identity_id) ON DELETE RESTRICT);
ALTER TABLE public.identity_profile OWNER TO subtrack_sandbox_owner;
ALTER TABLE public.merchant OWNER TO subtrack_sandbox_owner;
ALTER TABLE public.subscription OWNER TO subtrack_sandbox_owner;
ALTER TABLE public.manual_subscription_create_receipt OWNER TO subtrack_sandbox_owner;
ALTER TABLE public.manual_subscription_edit_receipt OWNER TO subtrack_sandbox_owner;
CREATE FUNCTION st250_auth.revision() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN IF NEW.identity_id<>OLD.identity_id OR NEW.id<>OLD.id OR NEW.source<>OLD.source OR NEW.always_private<>OLD.always_private OR NEW.revision<>OLD.revision THEN RAISE EXCEPTION 'Sandbox ownership is immutable' USING ERRCODE='23514';END IF;IF OLD.revision=9223372036854775807 THEN RAISE EXCEPTION 'Sandbox revision unavailable' USING ERRCODE='22003';END IF;NEW.revision=OLD.revision+1;RETURN NEW;END $$;
ALTER FUNCTION st250_auth.revision() OWNER TO subtrack_sandbox_owner;REVOKE ALL ON FUNCTION st250_auth.revision() FROM PUBLIC;
CREATE TRIGGER sandbox_subscription_revision BEFORE UPDATE ON public.subscription FOR EACH ROW EXECUTE FUNCTION st250_auth.revision();
CREATE FUNCTION st250_auth.guard_growth() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE owner_id uuid; retained bigint; owner_retained bigint;
BEGIN
 PERFORM id FROM st250_auth.capacity WHERE id=1 FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Sandbox capacity unavailable' USING ERRCODE='P0250';END IF;
 IF TG_TABLE_NAME='identity' THEN IF (SELECT count(*) FROM public.identity)>=100 THEN RAISE EXCEPTION 'Sandbox capacity unavailable' USING ERRCODE='P0250';END IF;RETURN NEW;END IF;
 IF TG_TABLE_NAME='reservation' THEN IF (SELECT count(*) FROM st250_auth.reservation)>=2048 THEN RAISE EXCEPTION 'Sandbox capacity unavailable' USING ERRCODE='P0250';END IF;RETURN NEW;END IF;
 owner_id=NEW.identity_id;PERFORM id FROM public.identity WHERE id=owner_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Sandbox owner unavailable' USING ERRCODE='23503';END IF;
 IF TG_TABLE_NAME='session' THEN SELECT count(*) INTO retained FROM st250_auth.session;SELECT count(*) INTO owner_retained FROM st250_auth.session WHERE identity_id=owner_id;IF retained>=3200 OR owner_retained>=32 OR NOT EXISTS(SELECT 1 FROM st250_auth.capability WHERE identity_id=owner_id AND revoked_ms IS NULL AND NEW.created_ms>=created_ms AND NEW.expires_ms<=expires_ms) THEN RAISE EXCEPTION 'Sandbox capacity unavailable' USING ERRCODE='P0250';END IF;
 ELSIF TG_TABLE_NAME='consumed_refresh' THEN IF (SELECT count(*) FROM st250_auth.consumed_refresh)>=3200 THEN RAISE EXCEPTION 'Sandbox capacity unavailable' USING ERRCODE='P0250';END IF;
 ELSIF TG_TABLE_NAME='subscription' THEN IF (SELECT count(*) FROM public.subscription WHERE identity_id=owner_id)>=50 THEN RAISE EXCEPTION 'Sandbox capacity unavailable' USING ERRCODE='P0250';END IF;IF NEW.revision<>1 OR NEW.merchant_id IS NOT NULL THEN RAISE EXCEPTION 'Sandbox manual row unavailable' USING ERRCODE='23514';END IF;
 ELSIF TG_TABLE_NAME IN('manual_subscription_create_receipt','manual_subscription_edit_receipt') THEN IF (SELECT count(*) FROM public.manual_subscription_create_receipt WHERE identity_id=owner_id)+(SELECT count(*) FROM public.manual_subscription_edit_receipt WHERE identity_id=owner_id)>=256 THEN RAISE EXCEPTION 'Sandbox capacity unavailable' USING ERRCODE='P0250';END IF;
 ELSE RAISE EXCEPTION 'Sandbox growth unavailable' USING ERRCODE='23514';END IF;RETURN NEW;
END $$;
ALTER FUNCTION st250_auth.guard_growth() OWNER TO subtrack_sandbox_owner;REVOKE ALL ON FUNCTION st250_auth.guard_growth() FROM PUBLIC;
CREATE TRIGGER sandbox_workspace_capacity BEFORE INSERT ON public.identity FOR EACH ROW EXECUTE FUNCTION st250_auth.guard_growth();
CREATE TRIGGER sandbox_admission_capacity BEFORE INSERT ON st250_auth.reservation FOR EACH ROW EXECUTE FUNCTION st250_auth.guard_growth();
CREATE TRIGGER sandbox_session_capacity BEFORE INSERT ON st250_auth.session FOR EACH ROW EXECUTE FUNCTION st250_auth.guard_growth();
CREATE TRIGGER sandbox_consumed_capacity BEFORE INSERT ON st250_auth.consumed_refresh FOR EACH ROW EXECUTE FUNCTION st250_auth.guard_growth();
CREATE TRIGGER sandbox_subscription_capacity BEFORE INSERT ON public.subscription FOR EACH ROW EXECUTE FUNCTION st250_auth.guard_growth();
CREATE TRIGGER sandbox_create_receipt_capacity BEFORE INSERT ON public.manual_subscription_create_receipt FOR EACH ROW EXECUTE FUNCTION st250_auth.guard_growth();
CREATE TRIGGER sandbox_edit_receipt_capacity BEFORE INSERT ON public.manual_subscription_edit_receipt FOR EACH ROW EXECUTE FUNCTION st250_auth.guard_growth();
ALTER TABLE public.identity_profile ENABLE ROW LEVEL SECURITY;ALTER TABLE public.identity_profile FORCE ROW LEVEL SECURITY;
ALTER TABLE public.merchant ENABLE ROW LEVEL SECURITY;ALTER TABLE public.merchant FORCE ROW LEVEL SECURITY;
ALTER TABLE public.subscription ENABLE ROW LEVEL SECURITY;ALTER TABLE public.subscription FORCE ROW LEVEL SECURITY;
ALTER TABLE public.manual_subscription_create_receipt ENABLE ROW LEVEL SECURITY;ALTER TABLE public.manual_subscription_create_receipt FORCE ROW LEVEL SECURITY;
ALTER TABLE public.manual_subscription_edit_receipt ENABLE ROW LEVEL SECURITY;ALTER TABLE public.manual_subscription_edit_receipt FORCE ROW LEVEL SECURITY;
CREATE POLICY profile_producer ON public.identity_profile FOR INSERT TO subtrack_sandbox_auth_producer WITH CHECK(public.subtrack_principal_matches(identity_id));
CREATE POLICY profile_owner_read ON public.identity_profile FOR SELECT TO subtrack_sandbox_runtime USING(public.subtrack_principal_matches(identity_id));
CREATE POLICY profile_owner_update ON public.identity_profile FOR UPDATE TO subtrack_sandbox_runtime USING(public.subtrack_principal_matches(identity_id)) WITH CHECK(public.subtrack_principal_matches(identity_id));
CREATE POLICY merchant_read ON public.merchant FOR SELECT TO subtrack_sandbox_runtime USING(true);
CREATE POLICY subscription_count ON public.subscription FOR SELECT TO subtrack_sandbox_owner USING(true);
CREATE POLICY subscription_owner_read ON public.subscription FOR SELECT TO subtrack_sandbox_runtime USING(public.subtrack_principal_matches(identity_id));
CREATE POLICY subscription_owner_insert ON public.subscription FOR INSERT TO subtrack_sandbox_runtime WITH CHECK(public.subtrack_principal_matches(identity_id));
CREATE POLICY subscription_owner_update ON public.subscription FOR UPDATE TO subtrack_sandbox_runtime USING(public.subtrack_principal_matches(identity_id)) WITH CHECK(public.subtrack_principal_matches(identity_id));
CREATE POLICY create_count ON public.manual_subscription_create_receipt FOR SELECT TO subtrack_sandbox_owner USING(true);
CREATE POLICY create_owner_read ON public.manual_subscription_create_receipt FOR SELECT TO subtrack_sandbox_runtime USING(public.subtrack_principal_matches(identity_id));
CREATE POLICY create_owner_insert ON public.manual_subscription_create_receipt FOR INSERT TO subtrack_sandbox_runtime WITH CHECK(public.subtrack_principal_matches(identity_id));
CREATE POLICY edit_count ON public.manual_subscription_edit_receipt FOR SELECT TO subtrack_sandbox_owner USING(true);
CREATE POLICY edit_owner_read ON public.manual_subscription_edit_receipt FOR SELECT TO subtrack_sandbox_runtime USING(public.subtrack_principal_matches(identity_id));
CREATE POLICY edit_owner_insert ON public.manual_subscription_edit_receipt FOR INSERT TO subtrack_sandbox_runtime WITH CHECK(public.subtrack_principal_matches(identity_id));
REVOKE ALL ON public.identity_profile,public.merchant,public.subscription,public.manual_subscription_create_receipt,public.manual_subscription_edit_receipt FROM PUBLIC;
GRANT SELECT ON public.identity_profile,public.merchant,public.subscription,public.manual_subscription_create_receipt,public.manual_subscription_edit_receipt TO subtrack_sandbox_runtime;
GRANT INSERT(identity_id,display_name,avatar_color,avatar_emoji,language,theme,default_currency,profile_complete,onboarding_mode) ON public.identity_profile TO subtrack_sandbox_auth_producer;
GRANT UPDATE(display_name,avatar_color,avatar_emoji,language,theme,profile_complete,onboarding_mode,updated_at) ON public.identity_profile TO subtrack_sandbox_runtime;
GRANT INSERT(id,identity_id,custom_name,category_code,cadence,expected_amount_minor,next_charge_date,source,status,currency,always_private,updated_at) ON public.subscription TO subtrack_sandbox_runtime;
GRANT UPDATE(custom_name,category_code,cadence,expected_amount_minor,next_charge_date,status,updated_at) ON public.subscription TO subtrack_sandbox_runtime;
GRANT INSERT ON public.manual_subscription_create_receipt,public.manual_subscription_edit_receipt TO subtrack_sandbox_runtime;
INSERT INTO st250_auth.migration VALUES(2,current_setting('st250.business_sha256'));
